<?php
require __DIR__.'/../app/bootstrap.php';$admin=require_admin();$search=trim((string)($_GET['q']??''));$status=(string)($_GET['status']??'all');$where=[];$params=[];
if($search!==''){$where[]='(p.name LIKE ? OR p.sku LIKE ?)';$params=['%'.$search.'%','%'.$search.'%'];}
if($status==='active')$where[]='p.is_active=1';elseif($status==='hidden')$where[]='p.is_active=0';
$sql='SELECT p.*,c.name AS category_name FROM products p JOIN categories c ON c.id=p.category_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.id DESC LIMIT 200';$products=all($sql,$params);
$admin_title='Quản lý sản phẩm';$admin_menu='products';require __DIR__.'/partials/header.php';
?>
<div class="admin-panel"><div class="admin-toolbar"><form action="<?= url('admin/products.php') ?>" method="get"><input type="search" name="q" placeholder="Tìm tên hoặc mã SKU..." value="<?= e($search) ?>"><select name="status"><option value="all">Tất cả</option><option value="active" <?= $status==='active'?'selected':'' ?>>Đang bán</option><option value="hidden" <?= $status==='hidden'?'selected':'' ?>>Đã ẩn</option></select><button type="submit" class="btn btn-outline"><i data-lucide="search"></i></button></form><a href="<?= url('admin/product_form.php') ?>" class="btn btn-primary"><i data-lucide="plus"></i> Thêm sản phẩm</a></div>
<table class="admin-table"><thead><tr><th>Ảnh</th><th>Sản phẩm</th><th>Danh mục</th><th>Giá bán</th><th>Kho</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>
<?php foreach($products as $p):?><tr><td><img class="thumb" src="<?= e(product_image($p['image'])) ?>" alt=""></td><td><strong><?= e(cut($p['name'],42)) ?></strong><br><small><?= e($p['sku']) ?> · <?= e($p['brand']) ?></small></td><td><?= e($p['category_name']) ?></td><td><strong style="color:var(--mint)"><?= money($p['price']) ?></strong></td><td><?= (int)$p['stock'] ?></td><td><span class="status <?= $p['is_active']?'completed':'cancelled' ?>"><?= $p['is_active']?'Đang bán':'Đã ẩn' ?></span></td><td><div class="admin-actions"><a href="<?= url('admin/product_form.php?id='.$p['id']) ?>">Sửa</a><form action="<?= url('admin/product_action.php') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><input type="hidden" name="action" value="toggle"><button type="submit"><?= $p['is_active']?'Ẩn':'Hiện' ?></button></form><form action="<?= url('admin/product_action.php') ?>" method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $p['id'] ?>"><input type="hidden" name="action" value="delete"><button type="submit" class="danger" data-confirm="Xóa vĩnh viễn sản phẩm này? Đơn hàng đã mua vẫn giữ bản ghi lịch sử.">Xóa</button></form></div></td></tr><?php endforeach; ?></tbody></table><?php if(!$products):?><p class="admin-empty">Không có sản phẩm phù hợp.</p><?php endif;?></div>
<?php require __DIR__.'/partials/footer.php';?>
